/* ---------- drawing helpers for this lesson (prefixed TH_ so they never clash with engine globals) ---------- */
const TH_F='font-family="Nunito Sans, sans-serif"';
const TH_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${TH_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const TH_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const TH_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??12}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const TH_head=(x2,y2,a,col,h=16)=>`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`;
const TH_arrow=(x1,y1,x2,y2,col='#18213A',w=3,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return TH_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+TH_head(x2,y2,a,col,h)};
const TH_GREY='#5C6577', TH_STEEL='#495057', TH_AL='#DEE2E6', TH_DK='#343A40', TH_STEAM='#E7F5FF', TH_WATER='#4DABF7';
/* the book's Mollier chart coordinates (s in kJ/kg·K, h in kJ/kg -> book px), mapped into a box at ox,oy with scale k */
const TH_bx=s=>90+(s-5.6)*150/0.7, TH_by=h=>210-(h-2750)*85/275;
const TH_DOME=[[659.0,264.6],[584.6,253.6],[521.0,243.1],[465.9,233.0],[417.7,223.6],[355.1,211.3],[300.9,201.6],[252.1,195.4],[206.2,193.6],[160.8,197.7],[112.7,210.1]];
const TH_P10=[[301.1,201.6],[307.5,197.4],[324.8,185.8],[374.2,150.3],[416.7,116.8],[454.9,83.8],[490.0,51.0]];
const TH_P1=[[207.3,372.7],[466.9,233.2],[479.0,226.6],[521.7,201.8],[569.1,171.2],[611.7,140.6],[650.8,109.7]];
const TH_pl=(pts,ox,oy,k,x0,y0,col,w,ex='')=>`<polyline points="${pts.map(([x,y])=>`${(ox+(x-x0)*k).toFixed(1)},${(oy+(y-y0)*k).toFixed(1)}`).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* a small h-s chart: book region x 90..690, y y0..y1 drawn at ox,oy with scale k; returns {svg, X(s), Y(h)} */
const TH_hs=(ox,oy,k,y0,o={})=>{const hg=o.hgt||300,X=s=>ox+(TH_bx(s)-90)*k, Y=h=>oy+(TH_by(h)-y0)*k,
  pl=(pts,col,w)=>`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>`;
 let s=TH_arrow(ox,oy+hg*k,ox,oy-6,TH_GREY,3,14)+TH_arrow(ox,oy+hg*k,ox+610*k,oy+hg*k,TH_GREY,3,14)
  +TH_T(ox+10,oy+14,'h',{fs:24,fw:800,fill:TH_GREY})+TH_T(ox+610*k-6,oy+hg*k-12,'s',{fs:24,fw:800,a:'end',fill:TH_GREY})
  +`<svg x="${ox}" y="${oy}" width="${(600*k).toFixed(1)}" height="${(hg*k).toFixed(1)}" viewBox="90 ${y0} 600 ${hg}" overflow="hidden">`+pl(TH_DOME,TH_GREY,4)+(o.p10?pl(TH_P10,BLU,4):'')+(o.p1?pl(TH_P1,BLU,4):'')+`</svg>`;
 return {svg:s,X,Y}};
const TH_dot=(x,y,col,r=9)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${col}" stroke="#FFFFFF" stroke-width="3"/>`;
/* a pressure gauge with its needle at angle a (degrees) */
const TH_gauge=(cx,cy,r,a,col)=>{const R=a*Math.PI/180;return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${TH_STEEL}" stroke-width="5"/>`+[-210,-165,-120,-75,-30].map(t=>{const T=t*Math.PI/180;return TH_L(cx+r*.74*Math.cos(T),cy+r*.74*Math.sin(T),cx+r*.9*Math.cos(T),cy+r*.9*Math.sin(T),TH_GREY,3)}).join('')+TH_L(cx,cy,cx+r*.72*Math.cos(R),cy+r*.72*Math.sin(R),col,5)+`<circle cx="${cx}" cy="${cy}" r="7" fill="${TH_DK}"/>`};
/* a throttle valve (the book's bow tie) centred at cx,cy */
const TH_valve=(cx,cy,s,col)=>`<path d="M${cx-s},${cy-s*.62} L${cx+s},${cy+s*.62} L${cx+s},${cy-s*.62} L${cx-s},${cy+s*.62} Z" fill="#DBE4FF" stroke="${col}" stroke-width="4" stroke-linejoin="round"/>`;
/* a pipe run with steam inside, from x1 to x2 at y, height h */
const TH_pipe=(x1,x2,y,h,o={})=>`<rect x="${x1}" y="${y-h/2}" width="${x2-x1}" height="${h}" rx="6" fill="${o.fill||TH_STEAM}" stroke="${o.st||TH_STEEL}" stroke-width="4"/>`;
const TH_drops=(pts,r=6)=>pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${TH_WATER}"/>`).join('');
/* a badge with a number, for trap pictures */
const TH_badge=(x,y,n)=>`<circle cx="${x}" cy="${y}" r="17" fill="${TRED}" fill-opacity="${TOP}"/>`+TH_T(x,y+8,n,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});

